declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\CanonicalMigrationApplication;use FMonitor2\InstallationProcess\ProductionPilotMigrationCatalogue;
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$admin=new mysqli($host,$user,$password,'',$port);$name='t_otiz_v2_upgrade_'.bin2hex(random_bytes(4));$db=null;
try{$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4");$db=new mysqli($host,$user,$password,$name,$port);$p='up_';$all=ProductionPilotMigrationCatalogue::migrations();$prior=array_filter($all,static fn($v)=>$v<=35,ARRAY_FILTER_USE_KEY);$old=CanonicalMigrationApplication::run($db,$p,$prior);assertSameValue(35,$old['result']['schemaVersion']??null,'supported predecessor v35');$hash=str_repeat('a',64);$db->query("INSERT INTO {$p}fm2_pilot_users(user_id,full_name,email,status,activation_state,source_updated_at)VALUES(1,'Old','old@example.test',1,'active','2026-09-01T00:00:00Z')");$db->query("INSERT INTO {$p}fm2_pilot_otiz_snapshots(id,report_date,status,rules_version,calculated_at,calculated_by_user_id,accepted_at,accepted_by_user_id,total_pool_cents,total_closed_cents,total_available_cents,content_hash)VALUES(9,'2026-09-01','accepted','legacy-v2','2026-09-01T00:00:00Z',1,'2026-09-01T01:00:00Z',1,1500000,0,1500000,'{$hash}')");$before=$db->query("SELECT * FROM {$p}fm2_pilot_otiz_snapshots WHERE id=9")->fetch_assoc();$full=CanonicalMigrationApplication::run($db,$p,$all);if(($full['result']['schemaVersion']??null)!==36){fwrite(STDERR,"INTENDED_RED: additive OTIZ v2 upgrade migration is absent\n");exit(1);}assertSameValue($before,$db->query("SELECT * FROM {$p}fm2_pilot_otiz_snapshots WHERE id=9")->fetch_assoc(),'upgrade preserves old snapshot bytes');foreach(['fm2_otiz_entitlement_claims','fm2_otiz_recipient_obligations','fm2_otiz_payment_facts']as$t)assertSameValue(1,(int)$db->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='{$p}{$t}'")->fetch_column(),'upgrade adds '.$t);assertSameValue(0,(int)$db->query("SELECT COUNT(*) FROM {$p}fm2_otiz_entitlement_claims")->fetch_column(),'upgrade does not invent historical claims');echo"settlement_v2_upgrade_001_test: OK\n";}finally{if($db instanceof mysqli)$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}